  let root=fs::canonicalize(&args[1])?;let executable=fs::canonicalize(std::env::current_exe()?)?;
  if snapshot{if hash(&read(&executable,64<<20)?)!=hash(&read(&root.join("bin/kelft-boundary"),64<<20)?){return Err("installed boundary snapshot differs".into());}}
