  let configuration=root.join("rootfs/control/linker.json");let configuration_bytes=read(&configuration,64<<20)?;if hash(&configuration_bytes)!=MACOS_LINKER_POLICY_SHA256{return Err("installed linker policy changed".into());}let linker=Linker::from_package(&configuration_bytes,&root)?;
  let public=root.join("rootfs/control/toolchain.json");let public_bytes=read(&public,1<<20)?;if hash(&public_bytes)!=MACOS_LINKER_SESSION_SHA256{return Err("installed linker session changed".into());}let value:serde_json::Value=serde_json::from_slice(&public_bytes)?;if value["identity"]!=linker.identity||value["profile"]!=Target::current()?.id(){return Err("linker session differs from private service".into());}
  let first=if command=="protocol"{5}else{4};if args.len()<first{return Err("installed compiler arguments missing".into());}let allowed:&[&str]=if command=="protocol"{&["--project-root","--output-root","--control-root","--fixtures-root","--ledger-root"]}else{&["--project-root","-o","--capabilities","--intent","--bindings","--object-output"]};let flags=Flags::parse(&args[first..],allowed,false)?;
